#!/usr/bin/env python3
# Generated by @ethlete/agent-rules — DO NOT EDIT. Run `npx ethlete-agents sync`.
"""Stop hook: keep a builder session working while the queue has rows for it.

A builder session (one that ran the `builder-agent` skill, or `/handoff resume
builder-...`) must not end a turn with free slots. When a turn ends with fewer
subagents and background commands running than the slot limit - a CI watcher or a
dev server does not count - and the queue (`plans/QUEUE.md`, rows owned by `Builder`) has open
rows without a wait reason, the stop is blocked and the reason names those rows, so
the turn goes on. The slot limit is `builderSlots` in the local config (default 4).

Agents started before a `/clear` are read from the meta files in the session's `subagents/`
directory (an unfinished meta whose launch is not in the transcript counts as running).

Running work comes from the transcript: every background Bash, Monitor and
async Agent start, minus every task-notification and every TaskStop for it. A
notification that says the agent "is waiting on its own background work" does not end it: the
agent has not handed back yet and notifies again when it does.

A row waits when its `Stand` cell (a checkbox row: its whole line) contains one of the wait
patterns, "wartet auf" or "Offen nur:" by default (case-insensitive). Table rows owned by anyone
else are skipped. A session counts as a builder when it ran the `builder-agent` skill or
`/handoff resume <role>-...` for a role in `roles` (default builder and coordinator).

A Codex run in a tmux session named `codex-<task>@<repo directory name>` counts as a running
subagent too: a builder starts them outside the transcript.

Fires at most once per idle stop chain: a stop that a Stop hook already
continued (`stop_hook_active`) passes.

Per-machine settings come from a gitignored ethlete-agents.config.local.json at
the repo root: {"disableHooks": true} or {"disableHooks": ["builder-idle-check"]}
disables the hook, {"builderSlots": 2} sets the slot limit. {"builderIdle": {...}} adapts the
queue for a consumer repo: "queues" is a list of {"path", "format"} (path relative to the repo
root, "../" allowed; format "table" for a QUEUE.md table or "checkbox" for `- [ ]` lines),
"waitPatterns" replaces the wait phrases, "roles" the session roles that count.

Fail-safe: any error exits 0 with no output.
"""

import json
import os
import re
import subprocess
import sys
from datetime import datetime

HOOK_NAME = "builder-idle-check"
LOCAL_CONFIG_FILE = "ethlete-agents.config.local.json"
DEFAULT_QUEUES = [{"path": os.path.join("plans", "QUEUE.md"), "format": "table"}]
QUEUE_OWNER = "Builder"
DEFAULT_SLOTS = 4
DEFAULT_WAIT_PATTERNS = ("wartet auf", "Offen nur:")
DEFAULT_ROLES = ("builder", "coordinator")
CHECKBOX_ROW = re.compile(r"^\s*[-*]\s+\[ \]\s+(.*)$")
ROW_ID = re.compile(r"^\*\*([^*]+)\*\*\s*(.*)$")

BUILDER_SKILL_LAUNCH = re.compile(
    r"Base directory for this skill: \S*/skills/builder-agent\b"
    r"|<command-name>/builder-agent</command-name>"
)
OTHER_ROLE_LAUNCH = re.compile(
    r"Base directory for this skill: \S*/skills/doc-agent\b"
    r"|<command-name>/doc-agent</command-name>"
    r"|<command-args>\s*resume\s+doc\b"
)
WATCHER_COMMAND = re.compile(
    r"\bgh\s+run\s+watch\b"
    r"|\bgh\s+pr\s+checks\b[^\n]*--watch\b"
    r"|\bglab\s+ci\s+(?:status|view)\b[^\n]*--live\b"
)
SERVER_COMMAND = re.compile(
    r"\b(?:npm|yarn)\s+(?:run\s+)?(?:storybook|serve|start|dev)\b"
    r"|\bnx\s+(?:serve\b|run\s+\S+:(?:serve|storybook)\b)"
    r"|\bstorybook\s+dev\b"
)
CI_POLL = re.compile(r"\b(?:gh\s+run\s+(?:view|list)|glab\s+ci\s+(?:status|list|get))\b")
LOOP = re.compile(r"\b(?:while|until|for)\b")
NOTIFICATION = re.compile(r"<task-notification>(.*?)</task-notification>", re.S)
WAITING_SUMMARY = re.compile(r"<summary>[^<]*is waiting on its own background work")
NOTIFICATION_IDS = re.compile(r"<(?:task-id|tool-use-id)>([^<]+)</(?:task-id|tool-use-id)>")
LINE_HINTS = ("tool_use", "task-notification", "builder", "doc-agent", "resume")


def repo_root(data):
    value = os.environ.get("CLAUDE_PROJECT_DIR")
    if value:
        return value
    cwd = data.get("cwd")
    return cwd if isinstance(cwd, str) and cwd else os.getcwd()


def read_local_config(root):
    try:
        with open(os.path.join(root, LOCAL_CONFIG_FILE), encoding="utf-8") as f:
            config = json.load(f)
    except (OSError, ValueError):
        return {}
    return config if isinstance(config, dict) else {}


def disabled_locally(config):
    disabled = config.get("disableHooks")
    return disabled is True or (isinstance(disabled, list) and HOOK_NAME in disabled)


def slot_limit(config):
    slots = config.get("builderSlots")
    if isinstance(slots, int) and not isinstance(slots, bool) and slots >= 1:
        return slots
    return DEFAULT_SLOTS


def builder_idle_config(config):
    value = config.get("builderIdle")
    return value if isinstance(value, dict) else {}


def string_list(value, default):
    if isinstance(value, list) and value and all(isinstance(item, str) and item for item in value):
        return tuple(value)
    return default


def queue_sources(settings):
    queues = settings.get("queues")
    if not isinstance(queues, list):
        return DEFAULT_QUEUES
    sources = [
        {"path": queue["path"], "format": "checkbox" if queue.get("format") == "checkbox" else "table"}
        for queue in queues
        if isinstance(queue, dict) and isinstance(queue.get("path"), str) and queue["path"]
    ]
    return sources or DEFAULT_QUEUES


def role_launch(roles):
    names = "|".join(re.escape(role) for role in roles)
    return re.compile(BUILDER_SKILL_LAUNCH.pattern + rf"|<command-args>\s*resume\s+(?:{names})\b")


def is_watcher(command):
    if WATCHER_COMMAND.search(command) or SERVER_COMMAND.search(command):
        return True
    return bool(CI_POLL.search(command) and LOOP.search(command) and "sleep" in command)


def parse_time(value):
    try:
        return datetime.fromisoformat(value.replace("Z", "+00:00")).timestamp()
    except (AttributeError, ValueError):
        return None


def texts_of(content):
    if isinstance(content, str):
        return [content]
    if isinstance(content, list):
        return [item.get("text", "") for item in content if isinstance(item, dict) and item.get("type") == "text"]
    return []


def read_transcript(path, launch):
    state = {"launch": launch, "builder": False, "tool_uses": {}, "tasks": {}, "done": set(), "now": None}
    with open(path, encoding="utf-8") as f:
        for raw in f:
            if not any(hint in raw for hint in LINE_HINTS):
                continue
            for chunk in NOTIFICATION.findall(raw.replace("\\n", "\n")):
                if not WAITING_SUMMARY.search(chunk):
                    state["done"].update(NOTIFICATION_IDS.findall(chunk))
            try:
                line = json.loads(raw)
            except ValueError:
                continue
            if not isinstance(line, dict) or line.get("isSidechain") or line.get("type") not in ("user", "assistant"):
                continue
            state["now"] = parse_time(line.get("timestamp")) or state["now"]
            message = line.get("message") or {}
            content = message.get("content")
            if line["type"] == "user":
                read_user_line(state, line, content)
            else:
                read_assistant_line(state, content)
    return state


def read_user_line(state, line, content):
    for text in texts_of(content):
        if state["launch"].search(text):
            state["builder"] = True
        elif OTHER_ROLE_LAUNCH.search(text):
            state["builder"] = False
    if not isinstance(content, list):
        return
    result = line.get("toolUseResult")
    if not isinstance(result, dict):
        return
    for item in content:
        if not isinstance(item, dict) or item.get("type") != "tool_result":
            continue
        use = state["tool_uses"].get(item.get("tool_use_id"))
        if not use:
            continue
        name, tool_input = use
        task_id = result.get("backgroundTaskId") or result.get("taskId")
        if task_id and name in ("Bash", "Monitor"):
            started = parse_time(line.get("timestamp"))
            timeout = result.get("timeoutMs")
            state["tasks"][task_id] = {
                "kind": "command",
                "tool_use_id": item.get("tool_use_id"),
                "label": tool_input.get("description") or tool_input.get("command", "")[:80],
                "watcher": is_watcher(tool_input.get("command", "")),
                "ends": started + timeout / 1000 if started and isinstance(timeout, (int, float)) else None,
            }
        elif result.get("agentId") and (
            result.get("isAsync") or result.get("status") in ("async_launched", "running", "in_process")
        ):
            state["tasks"][result["agentId"]] = {
                "kind": "agent",
                "tool_use_id": item.get("tool_use_id"),
                "label": tool_input.get("description", ""),
                "watcher": False,
                "ends": None,
            }


def read_assistant_line(state, content):
    if not isinstance(content, list):
        return
    for item in content:
        if not isinstance(item, dict) or item.get("type") != "tool_use":
            continue
        tool_input = item.get("input") if isinstance(item.get("input"), dict) else {}
        state["tool_uses"][item.get("id")] = (item.get("name"), tool_input)
        if item.get("name") == "Skill" and tool_input.get("skill") == "builder-agent":
            state["builder"] = True
        elif item.get("name") == "Skill" and tool_input.get("skill") == "doc-agent":
            state["builder"] = False
        elif item.get("name") == "TaskStop":
            state["done"].update(str(tool_input.get(key)) for key in ("task_id", "shell_id") if tool_input.get(key))


def read_earlier_agents(state, transcript_path):
    """Agents started before a /clear: their meta files sit in this session's subagents dir."""
    directory = os.path.join(os.path.splitext(transcript_path)[0], "subagents")
    try:
        names = sorted(os.listdir(directory))
    except OSError:
        return
    for name in names:
        if not (name.startswith("agent-") and name.endswith(".meta.json")):
            continue
        agent_id = name[len("agent-") : -len(".meta.json")]
        try:
            with open(os.path.join(directory, name), encoding="utf-8") as f:
                meta = json.load(f)
        except (OSError, ValueError):
            continue
        tool_use_id = meta.get("toolUseId") if isinstance(meta, dict) else None
        if not tool_use_id or meta.get("finished") or tool_use_id in state["tool_uses"] or agent_id in state["tasks"]:
            continue
        state["tasks"][agent_id] = {
            "kind": "agent",
            "tool_use_id": tool_use_id,
            "label": meta.get("description", ""),
            "watcher": False,
            "ends": None,
        }


def running_tasks(state):
    now = state["now"]
    return [
        task
        for task_id, task in state["tasks"].items()
        if task_id not in state["done"]
        and task["tool_use_id"] not in state["done"]
        and not (task["ends"] and now and now >= task["ends"])
    ]


def codex_runs(root):
    try:
        names = subprocess.run(
            ["tmux", "list-sessions", "-F", "#{session_name}"], capture_output=True, text=True, timeout=5
        ).stdout.split()
    except (OSError, subprocess.SubprocessError):
        return []
    suffix = "@" + os.path.basename(os.path.normpath(root))
    return [name for name in names if name.startswith("codex-") and name.endswith(suffix)]


def waits(text, patterns):
    lowered = text.lower()
    return any(pattern.lower() in lowered for pattern in patterns)


def open_table_rows(queue_text, patterns):
    rows = []
    stand_index = None
    for raw in queue_text.splitlines():
        if not raw.startswith("|"):
            continue
        cells = [cell.strip() for cell in raw.strip().strip("|").split("|")]
        if cells and cells[0] == "ID":
            stand_index = cells.index("Stand") if "Stand" in cells else None
            continue
        if stand_index is None or len(cells) <= stand_index or not re.fullmatch(r"[A-Z]+\d+", cells[0]):
            continue
        if cells[-1] == QUEUE_OWNER and not waits(cells[stand_index], patterns):
            rows.append(f"{cells[0]} ({cells[1]})")
    return rows


def open_checkbox_rows(queue_text, patterns):
    rows = []
    for raw in queue_text.splitlines():
        match = CHECKBOX_ROW.match(raw)
        if not match or waits(raw, patterns):
            continue
        text = match.group(1).strip()
        titled = ROW_ID.match(text)
        rows.append(f"{titled.group(1)} ({titled.group(2)[:60].strip()})" if titled else f"({text[:60].strip()})")
    return rows


def open_builder_rows(root, sources, patterns):
    rows = []
    for source in sources:
        try:
            with open(os.path.join(root, source["path"]), encoding="utf-8") as f:
                text = f.read()
        except OSError:
            continue
        read = open_checkbox_rows if source["format"] == "checkbox" else open_table_rows
        rows.extend(read(text, patterns))
    return rows


def not_taken(rows, labels):
    return [
        row
        for row in rows
        if row.startswith("(")
        or not any(re.search(rf"(?<![A-Za-z0-9]){re.escape(row.split(' ')[0])}(?![A-Za-z0-9])", label) for label in labels)
    ]


def reason_for(rows, watchers, working, slots, sources, patterns):
    watching = f" (still watching: {', '.join(watchers)})" if watchers else ""
    queues = ", ".join(source["path"] for source in sources)
    waiting = " or ".join(f'"{pattern}"' for pattern in patterns)
    return (
        f"[{HOOK_NAME} hook] This turn ends with {working} of {slots} slots in use, not counting CI watchers and dev servers{watching}, "
        f"while {queues} has open rows without a wait reason: {', '.join(rows)}. "
        "Do not leave slots idle: take the first of them now, or start a subagent on it. "
        f"A row waits when it contains {waiting}; if a row really waits, "
        "write the reason into the row. This hook fires once per idle stop."
    )


def main():
    try:
        data = json.load(sys.stdin)
        if not isinstance(data, dict) or data.get("stop_hook_active"):
            return
        root = repo_root(data)
        transcript_path = data.get("transcript_path")
        config = read_local_config(root)
        if disabled_locally(config) or not isinstance(transcript_path, str):
            return
        settings = builder_idle_config(config)
        roles = string_list(settings.get("roles"), DEFAULT_ROLES)
        state = read_transcript(transcript_path, role_launch(roles))
        if not state["builder"]:
            return
        read_earlier_agents(state, transcript_path)
        running = running_tasks(state)
        codex = codex_runs(root)
        working = sum(1 for task in running if not task["watcher"]) + len(codex)
        slots = slot_limit(config)
        if working >= slots:
            return
        sources = queue_sources(settings)
        patterns = string_list(settings.get("waitPatterns"), DEFAULT_WAIT_PATTERNS)
        watchers = [task["label"] for task in running] + codex
        rows = not_taken(open_builder_rows(root, sources, patterns), watchers)
        if not rows:
            return
        print(json.dumps({"decision": "block", "reason": reason_for(rows, watchers, working, slots, sources, patterns)}))
    except Exception:
        return


if __name__ == "__main__":
    main()
